import{_ as e,o as t,c as r,a5 as n}from"./chunks/framework.a5no_H3L.js";const f=JSON.parse('{"title":"性能优化概览","description":"游戏跑起来掉帧、卡顿，你想优化但不知道从哪下手。读完这一篇，你能识别游戏性能的三大瓶颈来源，理解 Draw Call 和 GC 这两个核心概念，并按清单系统排查。","frontmatter":{"type":"explanation","level":"advanced"},"headers":[],"relativePath":"unity/06-advanced/chapter-02-performance.md","filePath":"unity/06-advanced/chapter-02-performance.md"}'),i={name:"unity/06-advanced/chapter-02-performance.md"};function d(c,a,s,l,p,o){return t(),r("div",null,[...a[0]||(a[0]=[n(`<h1 id="性能优化概览" tabindex="-1" data-src-line="2" data-src-file="unity/06-advanced/chapter-02-performance.md">性能优化概览 <a class="header-anchor" href="#性能优化概览" aria-label="Permalink to &quot;性能优化概览&quot;">​</a></h1><p data-src-line="4" data-src-file="unity/06-advanced/chapter-02-performance.md">游戏跑起来掉帧、卡顿，你想优化但不知道从哪下手。读完这一篇，你能识别游戏性能的三大瓶颈来源，理解 Draw Call 和 GC 这两个核心概念，并按清单系统排查。</p><h2 id="_1-性能问题从哪里来" tabindex="-1" data-src-line="6" data-src-file="unity/06-advanced/chapter-02-performance.md">1. 性能问题从哪里来 <a class="header-anchor" href="#_1-性能问题从哪里来" aria-label="Permalink to &quot;1. 性能问题从哪里来&quot;">​</a></h2><p data-src-line="8" data-src-file="unity/06-advanced/chapter-02-performance.md">游戏的每一帧都要在约 16.7 毫秒内完成（60 FPS）。性能问题的本质是<strong>某件事占用了太多时间</strong>，导致一帧做不完。占用时间的主要有三处：</p><table tabindex="0"><thead data-src-line="10" data-src-file="unity/06-advanced/chapter-02-performance.md"><tr data-src-line="10" data-src-file="unity/06-advanced/chapter-02-performance.md"><th>来源</th><th>表现</th><th>典型原因</th></tr></thead><tbody data-src-line="12" data-src-file="unity/06-advanced/chapter-02-performance.md"><tr data-src-line="12" data-src-file="unity/06-advanced/chapter-02-performance.md"><td>CPU（脚本）</td><td>帧率低，Profiler 里脚本耗时高</td><td>每帧做昂贵操作、频繁查找、大量 GC</td></tr><tr data-src-line="13" data-src-file="unity/06-advanced/chapter-02-performance.md"><td>GPU（渲染）</td><td>帧率低，Rendering 耗时高</td><td>Draw Call 过多、模型面数高、纹理过大</td></tr><tr data-src-line="14" data-src-file="unity/06-advanced/chapter-02-performance.md"><td>内存</td><td>卡顿、闪退</td><td>只生成不销毁、资源泄漏、纹理未压缩</td></tr></tbody></table><p data-src-line="16" data-src-file="unity/06-advanced/chapter-02-performance.md">优化的第一步永远是<strong>用 Profiler 定位</strong>（见<a href="./../05-engineering/chapter-04-debugging-profiler.html">调试与 Profiler</a>），而不是凭感觉改。先知道瓶颈在哪，再针对优化。</p><h2 id="_2-draw-call-渲染的计数单位" tabindex="-1" data-src-line="18" data-src-file="unity/06-advanced/chapter-02-performance.md">2. Draw Call：渲染的计数单位 <a class="header-anchor" href="#_2-draw-call-渲染的计数单位" aria-label="Permalink to &quot;2. Draw Call：渲染的计数单位&quot;">​</a></h2><p data-src-line="20" data-src-file="unity/06-advanced/chapter-02-performance.md"><strong>Draw Call</strong> 是 CPU 告诉 GPU&quot;画一次&quot;的指令。每帧的 Draw Call 数量是渲染性能的关键指标。</p><ul data-src-line="22" data-src-file="unity/06-advanced/chapter-02-performance.md"><li data-src-line="22" data-src-file="unity/06-advanced/chapter-02-performance.md">场景里每个使用不同材质的物体，通常会产生一个或多个 Draw Call。</li><li data-src-line="23" data-src-file="unity/06-advanced/chapter-02-performance.md">1000 个各自独立的小物体，可能就有 1000 次 Draw Call，CPU 光是发指令就忙不过来。</li><li data-src-line="24" data-src-file="unity/06-advanced/chapter-02-performance.md">Draw Call 过多是移动端和低端机掉帧的头号原因。</li></ul><p data-src-line="26" data-src-file="unity/06-advanced/chapter-02-performance.md">优化的核心是<strong>减少 Draw Call</strong>，主要手段：</p><ul data-src-line="28" data-src-file="unity/06-advanced/chapter-02-performance.md"><li data-src-line="28" data-src-file="unity/06-advanced/chapter-02-performance.md"><strong>批处理（Batching）</strong>：把多个用相同材质的物体合并成一次绘制。静态物体勾选 <strong>Static Batching</strong>，动态物体靠 <strong>GPU Instancing</strong> 或共享材质。</li><li data-src-line="29" data-src-file="unity/06-advanced/chapter-02-performance.md"><strong>合并网格</strong>：把多个小模型合并成一个大模型，减少物体数量。</li><li data-src-line="30" data-src-file="unity/06-advanced/chapter-02-performance.md"><strong>共享材质</strong>：尽量让多个物体用同一个材质，而不是每个物体一个材质。</li></ul><p data-src-line="32" data-src-file="unity/06-advanced/chapter-02-performance.md">在 Profiler 的 Rendering 区域能看到 Draw Call 数量，优化前先记一个基线，优化后对比。</p><h2 id="_3-gc-垃圾回收的代价" tabindex="-1" data-src-line="34" data-src-file="unity/06-advanced/chapter-02-performance.md">3. GC：垃圾回收的代价 <a class="header-anchor" href="#_3-gc-垃圾回收的代价" aria-label="Permalink to &quot;3. GC：垃圾回收的代价&quot;">​</a></h2><p data-src-line="36" data-src-file="unity/06-advanced/chapter-02-performance.md">C# 有垃圾回收（GC），但 GC 不是免费的——它会扫描内存、回收不再使用的对象，这个过程可能暂停游戏。如果脚本每帧都创建大量临时对象，GC 频繁触发，就会造成周期性卡顿。</p><p data-src-line="38" data-src-file="unity/06-advanced/chapter-02-performance.md">Unity 里最大的性能杀手之一就是<strong>每帧分配（per-frame allocation）</strong>：</p><div class="language-csharp vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">csharp</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 反例：每帧都创建新字符串和数组，产生 GC 压力</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">void</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> Update</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">()</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    string</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> s</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;HP: &quot;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> +</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> health;                 </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 字符串拼接产生垃圾</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    var</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> results</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> GetComponentsInChildren</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">Enemy</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;();  </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 每帧分配数组</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p data-src-line="49" data-src-file="unity/06-advanced/chapter-02-performance.md">优化手段：</p><ul data-src-line="51" data-src-file="unity/06-advanced/chapter-02-performance.md"><li data-src-line="51" data-src-file="unity/06-advanced/chapter-02-performance.md"><strong>避免每帧创建对象</strong>：把 <code>new</code>、字符串拼接、<code>GetComponent</code> 这类操作移出 <code>Update</code>，放到 <code>Start</code> 缓存。</li><li data-src-line="52" data-src-file="unity/06-advanced/chapter-02-performance.md"><strong>用对象池（Object Pool）</strong>：频繁生成销毁的物体（子弹、敌人），预先创建一批、循环复用，而不是反复 <code>Instantiate</code>/<code>Destroy</code>。</li><li data-src-line="53" data-src-file="unity/06-advanced/chapter-02-performance.md"><strong>缓存组件引用</strong>：<code>GetComponent</code> 的结果缓存到字段，不要每帧调用。</li></ul><p data-src-line="55" data-src-file="unity/06-advanced/chapter-02-performance.md">判断是否有 GC 问题：Profiler 里看 <strong>GC Alloc</strong>（每帧分配量），或看帧率是否周期性波动（GC 触发时的特征）。</p><h2 id="_4-一个优化清单" tabindex="-1" data-src-line="57" data-src-file="unity/06-advanced/chapter-02-performance.md">4. 一个优化清单 <a class="header-anchor" href="#_4-一个优化清单" aria-label="Permalink to &quot;4. 一个优化清单&quot;">​</a></h2><p data-src-line="59" data-src-file="unity/06-advanced/chapter-02-performance.md">按优先级排列的排查清单：</p><ol data-src-line="61" data-src-file="unity/06-advanced/chapter-02-performance.md"><li data-src-line="61" data-src-file="unity/06-advanced/chapter-02-performance.md"><strong>Profiler 定位</strong>：先确认瓶颈在 CPU、GPU 还是内存，别瞎猜。</li><li data-src-line="62" data-src-file="unity/06-advanced/chapter-02-performance.md"><strong>减少 Draw Call</strong>：合并网格、共享材质、开批处理。</li><li data-src-line="63" data-src-file="unity/06-advanced/chapter-02-performance.md"><strong>消除每帧分配</strong>：缓存引用、移出 <code>new</code>、用对象池。</li><li data-src-line="64" data-src-file="unity/06-advanced/chapter-02-performance.md"><strong>检查物体数量</strong>：确认 <code>Instantiate</code> 都有对应的 <code>Destroy</code>，避免无限堆积。</li><li data-src-line="65" data-src-file="unity/06-advanced/chapter-02-performance.md"><strong>压缩资源</strong>：纹理用合适的分辨率和压缩格式，音频用合适格式。</li><li data-src-line="66" data-src-file="unity/06-advanced/chapter-02-performance.md"><strong>降低物理开销</strong>：减少不必要的 Rigidbody，合理设置 Fixed Timestep。</li></ol><h2 id="_5-优化与可读性的权衡" tabindex="-1" data-src-line="68" data-src-file="unity/06-advanced/chapter-02-performance.md">5. 优化与可读性的权衡 <a class="header-anchor" href="#_5-优化与可读性的权衡" aria-label="Permalink to &quot;5. 优化与可读性的权衡&quot;">​</a></h2><p data-src-line="70" data-src-file="unity/06-advanced/chapter-02-performance.md">性能优化要避免&quot;过度优化&quot;。原则是：</p><ul data-src-line="72" data-src-file="unity/06-advanced/chapter-02-performance.md"><li data-src-line="72" data-src-file="unity/06-advanced/chapter-02-performance.md"><strong>先让游戏能跑、能玩，再优化</strong>。过早优化会牺牲代码可读性，得不偿失。</li><li data-src-line="73" data-src-file="unity/06-advanced/chapter-02-performance.md"><strong>优化要有数据支撑</strong>。改之前 Profiler 记基线，改之后对比，确认真的变快了，而不是&quot;感觉快了&quot;。</li><li data-src-line="74" data-src-file="unity/06-advanced/chapter-02-performance.md"><strong>优先优化热点</strong>。Profiler 显示的最耗时的一两个点，往往贡献了大部分开销，集中改它们收益最大。</li></ul><p data-src-line="76" data-src-file="unity/06-advanced/chapter-02-performance.md">性能优化是持续的过程，不是一次性的。游戏开发中，先完成功能，再在关键时刻（明显卡顿、上线前）集中优化。</p><h2 id="_6-下一步" tabindex="-1" data-src-line="78" data-src-file="unity/06-advanced/chapter-02-performance.md">6. 下一步 <a class="header-anchor" href="#_6-下一步" aria-label="Permalink to &quot;6. 下一步&quot;">​</a></h2><p data-src-line="80" data-src-file="unity/06-advanced/chapter-02-performance.md">到这里，Unity 专题的正文全部结束。你已经走完&quot;上手 → 脚本 → 核心概念 → 玩法 → 工程实践 → 发布&quot;的完整路径。多人游戏、DOTS 等进阶主题属于后续扩展，需要时可回 <a href="./../">专题首页</a> 查看规划。</p>`,28)])])}const m=e(i,[["render",d]]);export{f as __pageData,m as default};
